struct sock *clone_and_lock_sock(const struct sock *sk, const struct request_sock *req, gfp_t priority) {
    struct sock *new_sk;

    new_sk = __sock_alloc(sk->sk_family, priority, NULL);
    if (!new_sk)
        return NULL;

    sock_lock_init(new_sk);
    new_sk->sk_state = TCP_SYN_RECV;

    new_sk->sk_daddr = req->rsk_dst.addr.all;
    new_sk->sk_rcv_saddr = req->rsk_src.addr.all;
    new_sk->sk_num = req->rsk_rcv_port;
    new_sk->sk_dport = req->rsk_sport;

    new_sk->sk_incoming_cpu = -1;
    sock_reset_flag(new_sk, SOCK_DEAD);

    sk_acceptq_removed(new_sk);
    security_sk_clone(new_sk, sk);

    return new_sk;
}

